  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `jeep_safaris` (10 rows)
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1, 'muruganpara-off-road-peak', 'Muruganmala / Muruganpara Off-Road Experience', '⛰️ Peak Safari', 'Thrilling rocky mountain ascent to 6,200+ ft with panoramic 360° views across Kerala & Tamil Nadu borders. High-altitude cool breeze and scenic rock formations.', '3 - 4 Hours', 'Rugged Climb', '₹2,500 – ₹3,500 per Jeep', 'Road conditions and summit mist vary with rain. Driver discretion applies.', '/assets/images/jeep_mountain_peak.jpg', '[]', 1, 1, 1, '2026-10-29 10:06:32', '2026-10-29 14:08:08') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (2, 'bhramaram-misty-mountain-point', 'Bhramaram Shooting Point', '🌫️ Misty Ridge', 'Famous movie shooting point ridge overlooking fruit orchards, deep fog carpets, and endless rolling Western Ghats. Unmatched sunrise & sunset visual views.', '2 - 3 Hours', 'Sunrise / Sunset', '₹2,000 – ₹3,000 per Jeep', 'Spectacular in morning fog and golden twilight.', '/assets/images/jeep_safari_mountain.jpg', NULL, 1, 2, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (3, 'irachilpara-kacharam-waterfalls', 'Irachilpara & Kacharam Waterfalls Trail', '🌊 Waterfall Trail', 'Off-road track winding deep through dense rainforest foliage and crystal boulder streams to secluded forest cascades. Seasonal natural plunge pools and cool sprays.', 'Half Day (3 - 4 Hours)', 'Natural Cascades', '₹2,500 – ₹3,500 per Jeep', 'Best flow during and after monsoon. Non-slip footwear recommended.', '/assets/images/jeep_green_forest.jpg', NULL, 1, 3, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (4, 'anakulam-wild-elephant-stream', 'Anakulam Wild Elephant Stream Safari', '🐘 Elephant Stream', 'Watch wild elephant herds gather naturally in the riverbed to drink mineral water, with safe 4x4 boulder-stream crossings and deep forest trails.', '4 - 5 Hours', 'Wildlife Sighting', '₹3,000 – ₹4,500 per Jeep', 'Natural wildlife sighting is subject to forest conditions and animal movement.', '/assets/images/jeep_adventure_real.jpg', NULL, 1, 4, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (5, 'sandalwood-forest-walk', 'Sandalwood Forest / Sandal Forest Walk', '🌿 Protected Heritage', 'Scenic drive through India\'s only natural reserve sandalwood forest maintained by Kerala Forest Dept. Guided walking trails through aromatic sandalwood trees.', '2 - 3 Hours', 'Protected Forest', 'Included in Marayoor tour packages', 'Restricted fenced forest zones require official forest department guide.', '/assets/images/dest_marayoor.jpg', NULL, 1, 5, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (6, 'kanthalloor-fruit-gardens', 'Kanthalloor Fruit Garden & Strawberry Orchards', '🍓 Fruit Orchards', 'Cool-climate terraced farm drive visiting apple, strawberry, plum, orange, and passion fruit plantations. Taste fresh seasonal fruits right off the tree.', '2 - 3 Hours', 'Terraced Farm Trail', 'Included in Kanthalloor packages', 'Fruit ripening and harvest depend on month and seasonal farm permissions.', '/assets/images/dest_kanthaloor.jpg', NULL, 1, 6, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (7, 'honey-rock-viewpoint', 'Honey Rock (Thenkoodu Para) Viewpoint', '🪨 Cliff View', 'Majestic cliff edge famous for giant natural wild bee combs hanging from rocky heights. Breathtaking valley views across tea and sugarcane plains.', '2 Hours', 'Scenic Valley Ridge', '₹1,500 – ₹2,500 per Jeep', 'Keep distance from rock edges and maintain environmental silence.', '/assets/images/hero_munnar_mountain.jpg', NULL, 1, 7, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (8, 'marayoor-jaggery-unit', 'Traditional Marayoor Jaggery Unit', '🍯 GI-Tagged Craft', 'Live visit to artisanal jaggery sheds where pure sugarcane juice is hand-boiled into the famous GI-tagged Marayoor Sharkara. Taste warm, fresh jaggery.', '1.5 - 2 Hours', 'Artisan Heritage', 'Included in Marayoor sightseeing', 'Live processing depends on farm production schedule and farm permissions.', '/assets/images/service_kerala_food.jpg', NULL, 1, 8, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (9, 'muniyara-megalithic-dolmens', 'Muniyara Megalithic Dolmens', '🪨 Ancient Heritage', 'Ancient stone burial chambers (Dolmens) dating back thousands of years to the Megalithic Iron Age, perched on rocky hills with vast valley panoramas.', '2 Hours', 'Archaeological Stone Trail', 'Included in Marayoor sightseeing', 'Protected archaeological site. Please respect historical monuments.', '/assets/images/dest_marayoor.jpg', NULL, 1, 9, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `jeep_safaris` (`id`, `slug`, `title`, `badge`, `description`, `duration`, `terrain_tag`, `price_info`, `weather_note`, `primary_image`, `gallery_images`, `is_featured_trail`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (10, 'zipline-adventure', 'Zipline Adventure Experience', '⚡ Thrill Ride', 'High-speed cable slide over verdant tea bushes and valley dips with professional safety harness. Superb adrenaline rush for young adults and families.', '1 Hour', 'Valley Aerial Cable', '₹500 – ₹800 per ride (separate ticket)', 'Subject to safe weather operations, wind conditions, and operator clearance.', '/assets/images/service_jeep_safari.jpg', NULL, 1, 10, 1, '2026-10-29 10:06:32', '2026-10-29 13:16:09') ON DUPLICATE KEY UPDATE `id`=`id`;

