CREATE TABLE IF NOT EXISTS `sightseeing_spots` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(150) NOT NULL,
  `location` varchar(150) NOT NULL,
  `timing` varchar(100) NOT NULL,
  `image` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `guidance` text NOT NULL,
  `badge` varchar(100) NOT NULL,
  `sort_order` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `sightseeing_spots` (7 rows)
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (1, 'Sandalwood Forest Walk', 'Marayoor – Chinnar Belt', '8:00 AM – 5:00 PM', '/assets/images/dest_marayoor.jpg', 'Natural reserve sandalwood forest maintained by Kerala Forest Department. Visitors can enjoy the scenic drive through fragrant sandalwood trees and observe natural conservation. Fenced forest zones are strictly protected; visitors must not enter fenced areas without an authorised forest department guide.', 'Restricted fenced forest zones require official permission; visitors may not enter fenced areas freely.', '🌿 Protected Heritage', 1) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (2, 'Irachalpara Waterfalls', 'Near Kanthalloor (12 km from Marayoor)', 'Daytime (Best 8:00 AM – 5:30 PM)', '/assets/images/jeep_green_forest.jpg', 'A multi-tiered scenic mountain waterfall secluded amidst dense Western Ghats rainforest foliage. Water flow is seasonal and most majestic during monsoon and post-monsoon months. Rocks can be slippery, so visitors should wear non-slip shoes and follow local safety instructions.', 'Monsoon and post-monsoon offer the best water cascade. Use non-slip footwear.', '🌊 Waterfall Trail', 2) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (3, 'Muniyara Megalithic Dolmens', 'Anakotta / Marayoor Rocky Ridge', 'Open Daytime', '/assets/images/dest_marayoor.jpg', 'Ancient stone burial chambers (Dolmens) dating back thousands of years to the Megalithic Iron Age, perched on rocky hills overlooking the picturesque Marayoor valley. As this is an archaeological heritage site, visitors are requested to respect monuments and avoid climbing on stone slabs.', 'Protected archaeological site. Please respect monuments and keep surroundings clean.', '🪨 Ancient Heritage', 3) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (4, 'Marayoor Jaggery Making Units', 'Marayoor Sugarcane Fields', 'Morning & Afternoon Production Hours', '/assets/images/service_kerala_food.jpg', 'Artisan jaggery sheds where the famous GI-tagged Marayoor Sharkara is traditionally hand-crafted from pure sugarcane juice boiled in large iron cauldrons. Live jaggery-making visits can be arranged when production units are operating and local producers permit visitors.', 'Live visits depend on operating production schedules and farm owner permissions.', '🍯 GI-Tagged Craft', 4) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (5, 'Kanthalloor Fruit & Strawberry Farms', 'Kanthalloor Terraced Valleys', '9:00 AM – 5:00 PM', '/assets/images/dest_kanthaloor.jpg', 'Cool-climate terraced orchards cultivating apples, strawberries, oranges, plums, peaches, and passion fruits. Farm walks and fruit harvesting depend on seasonal fruiting months and whether individual private family farms are open to guests on travel dates.', 'Farm entry and fruit availability vary seasonally. Always confirm harvest dates with guide.', '🍓 Fruit Orchards', 5) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (6, 'Thoovanam Waterfalls Trek', 'Chinnar Wildlife Sanctuary (Pambar River)', 'Morning Forest Batches (Subject to Forest Dept)', '/assets/images/dest_wayanad.jpg', 'A guided jungle trek through Chinnar Wildlife Sanctuary leading to the breathtaking Thoovanam waterfalls on the Pambar River. Trekking distance (~3-4 km), entry tickets, and an official Forest Department guide are mandatory under current sanctuary rules.', 'Official Forest Department permission, ticket and authorised forest guide are mandatory.', '🥾 Forest Trekking', 6) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `sightseeing_spots` (`id`, `title`, `location`, `timing`, `image`, `description`, `guidance`, `badge`, `sort_order`) VALUES (7, 'Anakulam Wild Elephant Viewing Area', 'Anakulam Riverbed (Near Mankulam)', 'Late Afternoon & Evening Hours', '/assets/images/dest_anakulam.jpg', 'A peaceful forest village river confluence where wild Asian elephant herds naturally emerge from the reserve forest to drink mineral-rich bubbling stream water. Sightings are completely wild and natural; visitors must stay on the safe village riverbank and follow forest safety protocols.', 'Natural wildlife sighting is not guaranteed; maintain safe distance and silence.', '🐘 Wild Elephant Stream', 7) ON DUPLICATE KEY UPDATE `id`=`id`;

