-- Dumping data for table `reviews` (5 rows)
INSERT INTO `reviews` (`id`, `name`, `location_tag`, `rating`, `review_text`, `sort_order`) VALUES (1, 'Karthik Sundaram', 'Chennai, Tamil Nadu • Family Holiday', 5, '\"Manoj bro is a genuine local legend! The 4x4 Jeep safari to Muruganpara and Bhramaram point was the highlight of our Kerala trip. Very safe driving by drivers Raja Durai and James, clean rooms in Kanthalloor, and wonderful home-cooked dinner!\"', 1) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `reviews` (`id`, `name`, `location_tag`, `rating`, `review_text`, `sort_order`) VALUES (2, 'Ashwin Nair', 'Kochi, Kerala • Friends Group Trip', 5, '\"Booked the ₹2,000 Anakulam package with friends. We saw wild elephants by the river stream in the evening! Campfire with music was unforgettable. Truly honest rates, authentic hospitality, and zero hidden charges at all.\"', 2) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `reviews` (`id`, `name`, `location_tag`, `rating`, `review_text`, `sort_order`) VALUES (3, 'Pooja & Rahul Sharma', 'Bangalore, Karnataka • Couple Getaway', 5, '\"The swimming pool property in Kanthalloor had incredible mountain views! Manoj coordinated our Munnar tea garden visit, fruit farm walk, and cab pickup from Coimbatore. 10/10 hospitality!\"', 3) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `reviews` (`id`, `name`, `location_tag`, `rating`, `review_text`, `sort_order`) VALUES (4, 'Vigneshwaran & Team', 'Coimbatore, Tamil Nadu • Weekend Trip', 5, '\"Staying at the Riverside Cottage near the river in Marayoor was the best decision! The sound of the flowing river stream and the night campfire were magical. Manoj\'s jeep safari was thrilling and safe.\"', 4) ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `reviews` (`id`, `name`, `location_tag`, `rating`, `review_text`, `sort_order`) VALUES (5, 'Dr. Ananya Sen', 'Hyderabad, Telangana • Family Holiday', 5, '\"We traveled with elderly parents and kids. Manoj treated us like his own family members. Comfortable rooms, prompt hot water, tasty homemade Kerala food, and relaxed sightseeing without rush. Highly recommended!\"', 5) ON DUPLICATE KEY UPDATE `id`=`id`;

